using System; using System.Collections.Generic; public class Heap<T> { private List<T> elements; private IComparer<T> comparer; public Heap(IComparer<T> comparer = null) { this.comparer = comparer ?? Comparer<T>.Default; this.elements = new List<T>(); } public void Add(T item) { elements.Add(item); HeapifyUp(elements.Count - 1); } public T Peek() { if (IsEmpty) throw new InvalidOperationException("Heap is empty."); return elements[0]; } public T Extract() { if (IsEmpty) throw new InvalidOperationException("Heap is empty."); T root = elements[0]; elements[0] = elements[elements.Count - 1]; elements.RemoveAt(elements.Count - 1); HeapifyDown(0); return root; } public int Count => elements.Count; public bool IsEmpty => elements.Count == 0; private void HeapifyUp(int index) { while (index > 0) { int parentIndex = (index - 1) / 2; if (comparer.Compare(elements[index], elements[parentIndex]) >= 0) break; Swap(index, parentIndex); index = parentIndex; } } private void HeapifyDown(int index) { int lastIndex = elements.Count - 1; while (index <= lastIndex) { int leftChildIndex = 2 * index + 1; int rightChildIndex = 2 * index + 2; int smallestIndex = index; if (leftChildIndex <= lastIndex && comparer.Compare(elements[leftChildIndex], elements[smallestIndex]) < 0) smallestIndex = leftChildIndex; if (rightChildIndex <= lastIndex && comparer.Compare(elements[rightChildIndex], elements[smallestIndex]) < 0) smallestIndex = rightChildIndex; if (smallestIndex == index) break; Swap(index, smallestIndex); index = smallestIndex; } } private void Swap(int indexA, int indexB) { T temp = elements[indexA]; elements[indexA] = elements[indexB]; elements[indexB] = temp; } }